import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"49、【革】 離下兌上","description":"橫渠易說 - 49、【革】 離下兌上","frontmatter":{"title":"49、【革】 離下兌上","description":"橫渠易說 - 49、【革】 離下兌上"},"headers":[],"relativePath":"classics/hengqu/051.md","filePath":"classics/hengqu/051.md"}'),l={name:"classics/hengqu/051.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_49、【革】-離下兌上" tabindex="-1">49、【革】 離下兌上 <a class="header-anchor" href="#_49、【革】-離下兌上" aria-label="Permalink to “49、【革】 離下兌上”">​</a></h1><h3 id="彖曰-革-水火相息-二女同居-其志不相得曰革。-巳日乃孚-革而信之-文明以說-大亨以正。革而當-其悔乃亡。" tabindex="-1">彖曰：革，水火相息，二女同居，其志不相得曰革。“巳日乃孚”，革而信之，文明以說，大亨以正。革而當，其悔乃亡。 <a class="header-anchor" href="#彖曰-革-水火相息-二女同居-其志不相得曰革。-巳日乃孚-革而信之-文明以說-大亨以正。革而當-其悔乃亡。" aria-label="Permalink to “彖曰：革，水火相息，二女同居，其志不相得曰革。“巳日乃孚”，革而信之，文明以說，大亨以正。革而當，其悔乃亡。”">​</a></h3><h3 id="天地革而四時成-湯武革命-順乎天而應乎人。革之時大矣哉-象曰-澤中有火-革-君子以治歷明時。" tabindex="-1">天地革而四時成，湯武革命，順乎天而應乎人。革之時大矣哉! 象曰：澤中有火，革，君子以治歷明時。 <a class="header-anchor" href="#天地革而四時成-湯武革命-順乎天而應乎人。革之時大矣哉-象曰-澤中有火-革-君子以治歷明時。" aria-label="Permalink to “天地革而四時成，湯武革命，順乎天而應乎人。革之時大矣哉! 象曰：澤中有火，革，君子以治歷明時。”">​</a></h3><h3 id="初九-鞏用黃牛之革。-象曰-鞏用黃牛-不可以有為也。" tabindex="-1">初九，鞏用黃牛之革。 象曰：“鞏用黃牛”，不可以有為也。 <a class="header-anchor" href="#初九-鞏用黃牛之革。-象曰-鞏用黃牛-不可以有為也。" aria-label="Permalink to “初九，鞏用黃牛之革。 象曰：“鞏用黃牛”，不可以有為也。”">​</a></h3><p>賤而無應，非大亨以正之德中堅自守，不可有為。</p><h3 id="六二-巳日乃革之-徵吉無咎。-象曰-巳日革之-行有嘉也。" tabindex="-1">六二，巳日乃革之，徵吉無咎。 象曰：“巳日革之”，行有嘉也。 <a class="header-anchor" href="#六二-巳日乃革之-徵吉無咎。-象曰-巳日革之-行有嘉也。" aria-label="Permalink to “六二，巳日乃革之，徵吉無咎。 象曰：“巳日革之”，行有嘉也。”">​</a></h3><p>俟上之唱，革而往應，柔中之德，所之乃吉。</p><h3 id="九三-徵兇貞厲-革言三就-有孚。-象曰-革言三就-又何之矣" tabindex="-1">九三，徵兇貞厲，革言三就，有孚。 象曰：“革言三就”，又何之矣! <a class="header-anchor" href="#九三-徵兇貞厲-革言三就-有孚。-象曰-革言三就-又何之矣" aria-label="Permalink to “九三，徵兇貞厲，革言三就，有孚。 象曰：“革言三就”，又何之矣!”">​</a></h3><p>以文明炎上剛陽之德進而之兌，兌內柔外剛，勢窮必反，故以徵則兇。能守正戒懼，文命告之，此三革言，彼三從命，必然可信之理也。一雲：徵則雖正而危。</p><h3 id="九四-悔亡有孚。改命吉。-象曰-改命之吉-信志也。" tabindex="-1">九四，悔亡有孚。改命吉。 象曰：改命之吉，信志也。 <a class="header-anchor" href="#九四-悔亡有孚。改命吉。-象曰-改命之吉-信志也。" aria-label="Permalink to “九四，悔亡有孚。改命吉。 象曰：改命之吉，信志也。”">​</a></h3><p>約己居陰，心無私系，革而必當，見孚於眾，改命倡始，信己可行，故吉。</p><h3 id="九五-大人虎變-未佔有孚。-象曰-大人虎變-其文炳也。" tabindex="-1">九五，大人虎變，未佔有孚。 象曰：“大人虎變”，其文炳也。 <a class="header-anchor" href="#九五-大人虎變-未佔有孚。-象曰-大人虎變-其文炳也。" aria-label="Permalink to “九五，大人虎變，未佔有孚。 象曰：“大人虎變”，其文炳也。”">​</a></h3><p>以剛居尊，說而唱下，為眾所睹，其文炳然，不卜而孚，望而可信，下觀而化，革著盛焉。 大人虎變，夫何疚之有! 虎變文章大，故明；豹變文章小，故蔚。</p><h3 id="上六-君子豹變-小人革面-徵兇-居貞吉。-象曰-君子豹變-其文蔚也-小人革面-順以從君也。" tabindex="-1">上六，君子豹變，小人革面，徵兇，居貞吉。 象曰：“君子豹變”，其文蔚也；“小人革面”，順以從君也。 <a class="header-anchor" href="#上六-君子豹變-小人革面-徵兇-居貞吉。-象曰-君子豹變-其文蔚也-小人革面-順以從君也。" aria-label="Permalink to “上六，君子豹變，小人革面，徵兇，居貞吉。 象曰：“君子豹變”，其文蔚也；“小人革面”，順以從君也。”">​</a></h3><p>以柔為德，不及九五剛中炳明，故但文章蔚縟，能使小人改觀而從也。 盛德之容，顏孟以上始可以觀。若顏子變則必大變，即大人虎變，虎變則其文至也，如此則不待佔而有信。君子所至之分以致文，則足以為班班之縟。革面而聽命，已不敢犯，此所謂盡飾之道，斯行者遠矣，然猶是就小成上以致其文。顏子地位，於豹變已為褻就，未必肯於此發見，此所以如愚。愚雖是於吾言無所不說，然必夫子省其私，始知不愚，察其人焉，惟是徇內尚質爾。然發則不小發， 大抵止乃有光明，艮曰“時止則止，時行則行，其道光明”，形則著，著則明，必能止則有光明。今作事特未決，蓋非止也，止乃決為，然後就其上文章。顏子見其進，未見其止，未止故未發見其所止，又必欲如所期，蓋未見夫子著心處，故未肯止，是之謂隱而未見，行而未成，是以勿用。學者至此地位，亦必如愚。然顏子(學)舉措亦無不致文中節處，自(是)謂“博我以文”，則文豈不足？但顏子不以為意，所謂“有若無，實若虛”也。有顏子之心，則不為顏子之文可也。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
